# Crea i prodotti di test SOLO se non esistono già (idempotente).
Product = env['product.product']
test_products = [
    {
        'name': 'Set 4 Sedie trasparenti - TEST',
        'barcode': '8056157802747',
        'default_code': 'TEST-SEDIE-4',
        'list_price': 99.0,
    },
]
created = []
for t in test_products:
    if not Product.search([('barcode', '=', t['barcode'])], limit=1):
        Product.create({
            'name': t['name'],
            'barcode': t['barcode'],
            'default_code': t['default_code'],
            'list_price': t['list_price'],
            'type': 'consu',
            'sale_ok': True,
        })
        created.append(t['barcode'])
log("BricoBravo prodotti di test creati: %s" % (created or 'nessuno (già presenti)'))
